CREATE OR REPLACE FUNCTION public.user_modules(_uid uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (CASE WHEN _uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid) THEN ARRAY[]::text[] WHEN public.has_role(_uid,'master') THEN ARRAY['agenda','historicos','oficina','os'] WHEN EXISTS(SELECT 1 FROM public.user_sectors WHERE user_id=_uid) THEN coalesce((SELECT array_agg(DISTINCT m ORDER BY m) FROM public.user_sectors us JOIN public.sectors s ON s.id=us.sector_id,unnest(s.modules) m WHERE us.user_id=_uid),ARRAY[]::text[]) WHEN public.has_role(_uid,'oficina') THEN ARRAY['oficina'] ELSE ARRAY['agenda','historicos','os'] END) || CASE WHEN public.can_view_vehicles(_uid) THEN ARRAY['veiculos'] ELSE ARRAY[]::text[] END $$;
CREATE FUNCTION public.validate_vehicle_plate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.plate:=public.norm_plate(NEW.plate); IF NEW.plate !~ '^[A-Z]{3}[A-Z0-9]{4}$' THEN RAISE EXCEPTION 'Informe uma placa válida com 7 caracteres'; END IF; IF EXISTS(SELECT 1 FROM public.vehicles v WHERE public.norm_plate(v.plate)=NEW.plate AND v.id<>NEW.id) THEN RAISE EXCEPTION 'Esta placa já está cadastrada'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_vehicle_plate BEFORE INSERT OR UPDATE OF plate ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.validate_vehicle_plate();
CREATE FUNCTION public.vehicle_workflow_lookup() RETURNS TABLE(plate text,modelo text,fabricante text,categoria text,km_atual integer,loja_op text,ano integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.plate,v.modelo,v.fabricante,v.categoria,v.km_atual,v.loja_op,v.ano FROM public.vehicles v WHERE v.active AND public.has_access(auth.uid()) AND public.has_module(auth.uid(),'os') $$;
REVOKE ALL ON FUNCTION public.vehicle_workflow_lookup() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.vehicle_workflow_lookup() TO authenticated;
CREATE FUNCTION public.log_vehicle_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_admin_log(actor_id,target_id,target_label,action,detail) VALUES(auth.uid(),NEW.user_id,'Acesso a Veículos','Acesso alterado',CASE WHEN NEW.allowed THEN 'Veículos permitido' ELSE 'Veículos bloqueado' END); RETURN NEW; END $$;
CREATE TRIGGER log_vehicle_access AFTER INSERT OR UPDATE ON public.vehicle_screen_access FOR EACH ROW EXECUTE FUNCTION public.log_vehicle_access();